-- Migration 145: pagamento acima do compromisso deixa de ser bloqueado.
-- Decisão do cliente (2026-07-28): "Alertar o usuário, que poderá confirmar ou
-- corrigir. Não impedir o registro."
-- ANTES: RAISE EXCEPTION 'Valor total pago não pode exceder o valor do compromisso'.
-- DEPOIS: a RPC aceita o excesso; o AVISO é responsabilidade do front (diálogo de
-- confirmação). Demais validações permanecem intactas.

CREATE OR REPLACE FUNCTION public.create_pagamento_conta_corrente_v2(p_conta_corrente_id bigint, p_data_pagamento date, p_forma_pagamento text, p_valor_pago numeric, p_arquivo_comprovante text DEFAULT NULL::text, p_categoria_id uuid DEFAULT NULL::uuid, p_forma_pagamento_id bigint DEFAULT NULL::bigint, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id bigint, conta_corrente_id bigint, data_pagamento date, forma_pagamento text, valor_pago numeric, categoria_id uuid, categoria_nome text, arquivo_comprovante text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ DECLARE v_new_id BIGINT; v_user_tipo TEXT; v_cliente_id BIGINT; v_valor_compromisso NUMERIC; v_valor_total_pago NUMERIC; v_forma_pagamento_nome TEXT; BEGIN IF p_conta_corrente_id IS NULL THEN RAISE EXCEPTION 'conta_corrente_id é obrigatório'; END IF; IF p_data_pagamento IS NULL THEN RAISE EXCEPTION 'data_pagamento é obrigatória'; END IF; IF p_forma_pagamento_id IS NOT NULL THEN SELECT ref_fp.nome INTO v_forma_pagamento_nome FROM public.ref_forma_pagamento ref_fp WHERE ref_fp.id = p_forma_pagamento_id AND (ref_fp.ativo IS NULL OR ref_fp.ativo = TRUE); IF NOT FOUND THEN RAISE EXCEPTION 'Forma de pagamento não encontrada ou inativa'; END IF; IF p_forma_pagamento IS NULL OR LENGTH(TRIM(p_forma_pagamento)) = 0 THEN ELSE v_forma_pagamento_nome := p_forma_pagamento; END IF; ELSE IF p_forma_pagamento IS NULL OR LENGTH(TRIM(p_forma_pagamento)) < 2 THEN RAISE EXCEPTION 'forma_pagamento é obrigatória e deve ter pelo menos 2 caracteres'; END IF; v_forma_pagamento_nome := TRIM(p_forma_pagamento); END IF; IF p_valor_pago IS NULL OR p_valor_pago <= 0 THEN RAISE EXCEPTION 'valor_pago deve ser maior que zero'; END IF; SELECT ccc.cliente_id, ccc.valor INTO v_cliente_id, v_valor_compromisso FROM public.conta_corrente_cliente ccc WHERE ccc.id = p_conta_corrente_id; IF NOT FOUND THEN RAISE EXCEPTION 'Compromisso não encontrado'; END IF; IF p_created_by IS NOT NULL THEN SELECT u.tipo INTO v_user_tipo FROM public.user u WHERE u.user_id = p_created_by AND u.ativo = TRUE AND u.deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado ou inativo'; END IF; IF v_user_tipo = 'vendedor' THEN IF NOT EXISTS (SELECT 1 FROM public.cliente_vendedores cv WHERE cv.cliente_id = v_cliente_id AND cv.vendedor_id = p_created_by) THEN RAISE EXCEPTION 'Vendedor não tem permissão para criar pagamento para este compromisso'; END IF; END IF; END IF; SELECT COALESCE(SUM(pac.valor_pago), 0) INTO v_valor_total_pago FROM public.pagamento_acordo_cliente pac WHERE pac.conta_corrente_id = p_conta_corrente_id; /* (145) excesso permitido: aviso no front, sem bloquear o registro. */ INSERT INTO public.pagamento_acordo_cliente (conta_corrente_id, data_pagamento, forma_pagamento, forma_pagamento_id, valor_pago, categoria_id, arquivo_comprovante, created_at) VALUES (p_conta_corrente_id, p_data_pagamento, v_forma_pagamento_nome, p_forma_pagamento_id, p_valor_pago, p_categoria_id, p_arquivo_comprovante, NOW()) RETURNING pagamento_acordo_cliente.id INTO v_new_id; RETURN QUERY SELECT pac.id AS id, pac.conta_corrente_id AS conta_corrente_id, pac.data_pagamento AS data_pagamento, pac.forma_pagamento AS forma_pagamento, pac.valor_pago AS valor_pago, pac.categoria_id AS categoria_id, cat.nome AS categoria_nome, pac.arquivo_comprovante AS arquivo_comprovante, pac.created_at AS created_at FROM public.pagamento_acordo_cliente pac LEFT JOIN public.categorias_conta_corrente cat ON cat.id = pac.categoria_id AND cat.deleted_at IS NULL WHERE pac.id = v_new_id; EXCEPTION WHEN OTHERS THEN RAISE LOG 'Error in create_pagamento_conta_corrente_v2: %', SQLERRM; RAISE; END; $function$
;
